import 'package:build/build.dart';
import 'package:build_test/build_test.dart';
import 'package:go_router_aggregator/go_router_aggregator.dart';
import 'package:test/test.dart';

const _header = '''
// GENERATED by go_router_aggregator - do NOT edit by hand - contents will be overridden
// ignore_for_file: type=lint
import 'package:go_router/go_router.dart';
''';

/// Content of a part file emitted by go_router_builder.
const _routesPart = r'''
List<RouteBase> get $appRoutes => [$fooRoute];

RouteBase get $fooRoute => GoRouteData.$route(
  path: '/foo',
  factory: _$FooRoute._fromState,
);
''';

Future<void> _expectOutput(
  Map<String, String> inputs,
  String expected, {
  Map<String, Object?> config = const {},
  String outputPath = 'lib/routes.g.dart',
}) => testBuilder(
  aggregateAppRoutes(BuilderOptions(config)),
  inputs,
  outputs: {'app|$outputPath': expected},
);

void main() {
  group('AggregateAppRoutesBuilder', () {
    test('emits an empty list if no routes are present', () async {
      await _expectOutput(
        {
          'app|lib/unused.g.dart': '// generated code without routes',
          'app|lib/unused.json_serializable.g.part': '// not a route part',
        },
        '''
$_header
List<RouteBase> get \$aggregatedRoutes => [];
''',
      );
    });

    test('aggregates a single route library', () async {
      await _expectOutput(
        {
          'app|lib/foo.dart': 'class FooRoute {}',
          'app|lib/foo.go_router.g.part': _routesPart,
        },
        '''
$_header
import 'package:app/foo.dart' as _foo;

List<RouteBase> get \$aggregatedRoutes => [..._foo.\$appRoutes];
''',
      );
    });

    test('aggregates multiple libraries sorted by path', () async {
      await _expectOutput(
        {
          'app|lib/settings/settings_page.go_router.g.part': _routesPart,
          'app|lib/app_routes.go_router.g.part': _routesPart,
          'app|lib/home/home_page.go_router.g.part': _routesPart,
        },
        '''
$_header
import 'package:app/app_routes.dart' as _app_routes;
import 'package:app/home/home_page.dart' as _home_home_page;
import 'package:app/settings/settings_page.dart' as _settings_settings_page;

List<RouteBase> get \$aggregatedRoutes => [
  ..._app_routes.\$appRoutes,
  ..._home_home_page.\$appRoutes,
  ..._settings_settings_page.\$appRoutes,
];
''',
      );
    });

    test('respects a custom output path', () async {
      await _expectOutput(
        {'app|lib/bar.go_router.g.part': _routesPart},
        config: {'output': ' ./src/nav/app.g.dart '},
        outputPath: 'lib/src/nav/app.g.dart',
        '''
$_header
import 'package:app/bar.dart' as _bar;

List<RouteBase> get \$aggregatedRoutes => [..._bar.\$appRoutes];
''',
      );
    });

    test('includes libraries whose name ends with the output name', () async {
      await _expectOutput(
        {
          'app|lib/routes.go_router.g.part': _routesPart,
          'app|lib/nested/routes.go_router.g.part': _routesPart,
        },
        '''
$_header
import 'package:app/nested/routes.dart' as _nested_routes;
import 'package:app/routes.dart' as _routes;

List<RouteBase> get \$aggregatedRoutes => [
  ..._nested_routes.\$appRoutes,
  ..._routes.\$appRoutes,
];
''',
      );
    });

    test('creates valid unique prefixes for any file names', () async {
      await _expectOutput(
        {
          'app|lib/foo/foo.go_router.g.part': _routesPart,
          'app|lib/bar/foo.go_router.g.part': _routesPart,
          'app|lib/my-page.go_router.g.part': _routesPart,
          'app|lib/my_page.go_router.g.part': _routesPart,
        },
        '''
$_header
import 'package:app/bar/foo.dart' as _bar_foo;
import 'package:app/foo/foo.dart' as _foo_foo;
import 'package:app/my-page.dart' as _my_page;
import 'package:app/my_page.dart' as _my_page1;

List<RouteBase> get \$aggregatedRoutes => [
  ..._bar_foo.\$appRoutes,
  ..._foo_foo.\$appRoutes,
  ..._my_page.\$appRoutes,
  ..._my_page1.\$appRoutes,
];
''',
      );
    });

    test('ignores route parts outside of lib/', () async {
      await _expectOutput(
        {
          'app|lib/foo.go_router.g.part': _routesPart,
          'app|test/foo.go_router.g.part': _routesPart,
        },
        '''
$_header
import 'package:app/foo.dart' as _foo;

List<RouteBase> get \$aggregatedRoutes => [..._foo.\$appRoutes];
''',
      );
    });

    group('rejects invalid output paths:', () {
      for (final output in [
        42,
        '',
        '/abs/routes.g.dart',
        '../routes.g.dart',
        'lib/routes.g.dart',
        'routes.g',
      ]) {
        test('$output', () {
          expect(
            () => aggregateAppRoutes(BuilderOptions({'output': output})),
            throwsArgumentError,
          );
        });
      }
    });
  });
}
